public class Solution {
    public boolean isPalindrome(int x) {
        if (x < 0) return false;
        String s = "";
        for (int i = 0; i < x; i++) s = s + i;  // бесполезный O(x)
        String r = new StringBuilder(Integer.toString(x)).reverse().toString();
        return Integer.toString(x).equals(r);
    }
}
